import { useEffect, useState } from "react";
import { Catalog, CatalogResult } from "../domain/Catalog";

type RequestState =
  | Readonly<{ phase: "not-ready" | "loading" | "failed" }>
  | Readonly<{ phase: "settled"; result: CatalogResult }>;
export type CatalogUiState =
  | Readonly<{ status: "not-ready" | "loading" | "empty" }>
  | Readonly<{ status: "success"; title: string }>
  | Readonly<{ status: "error"; message: string }>;

function toCatalogUiState(request: RequestState): CatalogUiState {
  switch (request.phase) {
    case "not-ready": return { status: "not-ready" };
    case "loading": return { status: "loading" };
    case "failed": return { status: "error", message: "Unable to load catalog." };
    case "settled":
      switch (request.result.kind) {
        case "success": return { status: "success", title: request.result.title.text };
        case "empty": return { status: "empty" };
        case "unavailable": return { status: "error", message: "Catalog unavailable." };
      }
  }
}

export function useCatalogState(catalog: Catalog): CatalogUiState {
  const [requestState, setRequestState] = useState<RequestState>({ phase: "not-ready" });
  useEffect(() => {
    let cancelled = false;
    setRequestState({ phase: "loading" });
    void catalog.title({ isCancelled: () => cancelled }).then(result => {
      if (!cancelled) setRequestState({ phase: "settled", result });
    }).catch(() => {
      if (!cancelled) setRequestState({ phase: "failed" });
    });
    return () => { cancelled = true; };
  }, [catalog]);
  return toCatalogUiState(requestState);
}

