function CatalogView({ uiState }: { uiState: CatalogUiState }) {
  switch (uiState.status) {
    case "not-ready": return <p>Catalog not loaded.</p>;
    case "loading": return <p role="status">Loading catalog.</p>;
    case "empty": return <p>No catalog available.</p>;
    case "error": return <p role="alert">{uiState.message}</p>;
    case "success": return <h1>{uiState.title}</h1>;
  }
}

