import { useCallback, useEffect, useRef, useState } from "react";
import { Cancellation } from "../domain/CheckoutPorts";
type UiState = Readonly<{ status: "ready" | "working" | "success" }> | Readonly<{ status: "error"; message: string }>;
export function useCheckoutOperation(operation: (cancellation: Cancellation) => Promise<void>) {
  const [uiState, setUiState] = useState<UiState>({ status: "ready" });
  const active = useRef<{ cancelled: boolean } | null>(null);
  useEffect(() => () => { if (active.current) active.current.cancelled = true; }, []);
  const checkout = useCallback(async () => {
    if (active.current) return;
    const request = { cancelled: false };
    active.current = request;
    setUiState({ status: "working" });
    try {
      await operation({ isCancelled: () => request.cancelled });
      if (!request.cancelled) setUiState({ status: "success" });
    } catch {
      if (!request.cancelled) setUiState({ status: "error", message: "Checkout failed." });
    } finally {
      if (active.current === request) active.current = null;
    }
  }, [operation]);
  return { uiState, checkout };
}

