import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update

sealed interface PageState {
    data class Content(val count: Int) : PageState
}
sealed interface Effect {
    data object Increment : Effect
    data object OpenDetails : Effect
}
sealed interface Event { data object Navigate : Event }
class PageHolder(private val emitEvent: (Event) -> Unit) {
    private val mutableState = MutableStateFlow<PageState>(PageState.Content(0))
    val uiState = mutableState.asStateFlow()
    fun onEffect(input: Effect) {
        when (input) {
            Effect.Increment -> mutableState.update { state ->
                when (state) {
                    is PageState.Content -> state.copy(count = state.count + 1)
                }
            }
            Effect.OpenDetails -> emitEvent(Event.Navigate)
        }
    }
}

