import { useCallback, useState } from "react";
type Validation = Readonly<{ status: "untouched" | "valid" }> | Readonly<{ status: "invalid"; message: string }>;
export function useEmailValidation() {
  const [validation, setValidation] = useState<Validation>({ status: "untouched" });
  const onInvalidEmail = useCallback((message: string) => setValidation({ status: "invalid", message }), []);
  const onValidEmail = useCallback(() => setValidation({ status: "valid" }), []);
  return { validation, onInvalidEmail, onValidEmail };
}
